            List<String> paths = Lists.newArrayList(keyBuilder.resourceConfigs().getPath(), keyBuilder.idealStates().getPath(), keyBuilder.externalViews().getPath(), PropertyPathConfig.getPath(PropertyType.PROPERTYSTORE, CLUSTER_NAME) + TaskConstants.REBALANCER_CONTEXT_ROOT);
