                // make sure MasterSlave is not over-written
                if (def == BuiltInStateModelDefinitions.MasterSlave) {
                    Stat stat = new Stat();
                    baseAccessor.get(path, stat, 0);
                    if (stat.getVersion() != 0) {
                        return false;
                    }
                }
            }
            return true;
        }
