/**
 * The validator should fail on any detected infinite loops
 */
@Test
public void testLoopInStateModel() {
    // create an infinite loop ONE --> TWO --> ONE
    ZNRecord record = new ZNRecord("MasterSlave");
    record.setSimpleField(StateModelDefinitionProperty.INITIAL_STATE.toString(), "OFFLINE");
    List<String> statePriorityList = Lists.newArrayList("ONE", "TWO", "THREE", "OFFLINE", "DROPPED", "ERROR");
    record.setListField(StateModelDefinitionProperty.STATE_PRIORITY_LIST.toString(), statePriorityList);
    for (String state : statePriorityList) {
        String key = state + ".meta";
        Map<String, String> metadata = new HashMap<String, String>();
        metadata.put("count", "-1");
        record.setMapField(key, metadata);
    }
    for (String state : statePriorityList) {
        String key = state + ".next";
        if (state.equals("ONE")) {
            Map<String, String> metadata = new HashMap<String, String>();
            metadata.put("THREE", "TWO");
            metadata.put("TWO", "TWO");
            metadata.put("OFFLINE", "OFFLINE");
            metadata.put("DROPPED", "DROPPED");
            record.setMapField(key, metadata);
        } else if (state.equals("TWO")) {
            Map<String, String> metadata = new HashMap<String, String>();
            metadata.put("THREE", "ONE");
            metadata.put("OFFLINE", "OFFLINE");
            metadata.put("DROPPED", "OFFLINE");
            record.setMapField(key, metadata);
        } else if (state.equals("THREE")) {
            Map<String, String> metadata = new HashMap<String, String>();
            metadata.put("OFFLINE", "OFFLINE");
            metadata.put("DROPPED", "OFFLINE");
            record.setMapField(key, metadata);
        } else if (state.equals("OFFLINE")) {
            Map<String, String> metadata = new HashMap<String, String>();
            metadata.put("ONE", "ONE");
            metadata.put("TWO", "TWO");
            metadata.put("THREE", "THREE");
            metadata.put("DROPPED", "DROPPED");
            record.setMapField(key, metadata);
        } else if (state.equals("ERROR")) {
            Map<String, String> metadata = new HashMap<String, String>();
            metadata.put("OFFLINE", "OFFLINE");
            record.setMapField(key, metadata);
        }
    }
    List<String> stateTransitionPriorityList = new ArrayList<String>();
    record.setListField(StateModelDefinitionProperty.STATE_TRANSITION_PRIORITYLIST.toString(), stateTransitionPriorityList);
    StateModelDefinition stateModel = new StateModelDefinition(record);
    Assert.assertFalse(stateModel.isValid());
}

/**
 * This is the example used on the website, so this must work
 */
@Test
public void testBasic() {
    StateModelDefinition stateModel = new StateModelDefinition.Builder("MasterSlave").// OFFLINE is the state that the system starts in (initial state is REQUIRED)
    initialState("OFFLINE").// Lowest number here indicates highest priority, no value indicates lowest priority
    addState("MASTER", 1).addState("SLAVE", 2).addState("OFFLINE").// Note the special inclusion of the DROPPED state (REQUIRED)
    addState(HelixDefinedState.DROPPED.toString()).// No more than one master allowed
    upperBound("MASTER", 1).// R indicates an upper bound of number of replicas for each partition
    dynamicUpperBound("SLAVE", "R").// Add some high-priority transitions
    addTransition("SLAVE", "MASTER", 1).addTransition("OFFLINE", "SLAVE", 2).// Using the same priority value indicates that these transitions can fire in any order
    addTransition("MASTER", "SLAVE", 3).addTransition("SLAVE", "OFFLINE", 3).// Not specifying a value defaults to lowest priority
    // Notice the inclusion of the OFFLINE to DROPPED transition
    // Since every state has a path to OFFLINE, they each now have a path to DROPPED (REQUIRED)
    addTransition("OFFLINE", HelixDefinedState.DROPPED.toString()).// Create the StateModelDefinition instance
    build();
    Assert.assertTrue(stateModel.isValid());
}

